namespace MyApp.Domain;

internal sealed class ExperimentalPricingEngine
{
    internal decimal Quote(decimal basePrice) => basePrice * 1.1m;
}

public sealed class PricingFacade
{
    private readonly ExperimentalPricingEngine _engine = new();
    public decimal GetQuote(decimal basePrice) => _engine.Quote(basePrice);
}
